<template><div class="section"><div class="container"><div class="section-head"><span class="kicker">THE JOURNAL</span><h1>Won Nyaci Run stories.</h1><p class="section-lead">Announcements, partner stories, training tips, culture and community impact.</p></div><div v-if="posts.length" class="posts-grid"><article v-for="post in posts" :key="post.id" class="post-card"><img v-if="post.image" class="post-image" :src="asset(post.image)"/><div v-else class="post-image"></div><div class="post-body"><small>{{format(post.published_at)}}</small><h3>{{post.title}}</h3><p>{{post.excerpt||truncate(post.body)}}</p><RouterLink :to="`/blog/${post.slug}`" class="btn btn-primary">Read →</RouterLink></div></article></div><div v-else class="culture-card"><h3>No published stories yet.</h3><p>Admin users can publish stories and attach photos from the CMS.</p></div></div></div></template>
<script setup>import {ref,onMounted} from 'vue';import axios from 'axios';const posts=ref([]);const asset=p=>p?.startsWith('http')?p:(p?.startsWith('images/')?`/${p}`:`/storage/${p}`);const truncate=t=>t?.length>160?t.slice(0,160)+'…':t;const format=d=>d?new Date(d).toLocaleDateString():'';onMounted(async()=>{posts.value=(await axios.get('/api/posts')).data.data||[]})</script>
